import{S as t,o as e,c as n,a9 as h,B as l}from"./chunks/framework.IJ8axLs_.js";const p="/agentsrc/images/deepseek/02-context-derive.svg",k="/agentsrc/images/deepseek/02-event-modes.svg",d="/agentsrc/images/deepseek/02-scope-chain.svg",g=JSON.parse('{"title":"Cordis 组合框架：插件靠什么拼成树","description":"","frontmatter":{"title":"Cordis 组合框架：插件靠什么拼成树"},"headers":[],"relativePath":"deepseek/02-cordis.md","filePath":"deepseek/02-cordis.md","lastUpdated":1790217011000}'),o={name:"deepseek/02-cordis.md"},y=Object.assign(o,{setup(r){const i=[{question:"Cordis 里插件之间定位彼此的服务，靠什么？",options:["import 对方包的导出类","在 context 上按稳定键读写","走全局单例注册中心","由配置文件硬编码绑定"],correct:1,explanation:"Context 是服务仓库：服务占一个 `ctx.<key>`，使用方按键取用而非 import 实现，所以换实现只是换注册到该键的插件。A 会把使用方绑死在实现包上，C/D 都不是 Cordis 的机制。"},{question:"一个 waterfall 监听者不调 `next()` 直接返回，后果是？",options:["整条链只剩内置行为执行","框架自动替它补调 next","链条其余环节与内置行为都被否决","运行时抛 CordisError"],correct:2,explanation:"waterfall 的语义：不调 next 即否决，链条剩下的监听者连同最内端的内置行为都不会执行。A 说反了，B 不存在这种兜底，D 是对已销毁 fiber 注册时才会抛的错。"},{question:"几十个插件的加载顺序，Cordis 靠什么决定？",options:["按 cordis.yml 的行位依次启动","按包名字典序加载","由 root 插件手动编排","由 inject 声明的服务依赖推导"],correct:3,explanation:"条目并发启动、行位不保证顺序；声明了 `inject` 的插件等所需服务全部到位才激活，顺序从依赖图推导出来。A 与事实相反，B/C 的机制不存在。"},{question:"关于 `dsh-scope` 的定位，正确的说法是？",options:["它是同进程的信任路由，不是沙箱","它是不可绕过的安全边界","它只影响事件，不管注册的回收","它只能在 web profile 下生效"],correct:0,explanation:"README 明确 scope 路由可信的同进程插件、不是沙箱或权限边界；安全隔离由沙箱与审批策略负责。B 夸大了它的安全承诺，C 漏掉了它对注册生命周期的所有权，D 无此限制。"},{question:"一个插件通过 `ctx.on()` 注册的监听器，什么时候被摘除？",options:["等进程退出时才统一清理","事件触发满一次后自动移除","插件所在 fiber 卸载时自动回滚","需要手动调用全局清理接口"],correct:2,explanation:"监听器作为 effect 存进当前 fiber 的卸载项，fiber 卸载进入 UNLOADING 时逆序执行 disposer。B 说的是 `once()`，A/D 都不是这套生命周期模型。"}];return(c,s)=>{const a=t("Quiz");return e(),n("div",null,[s[0]||(s[0]=h("",64)),l(a,{questions:i})])}}});export{g as __pageData,y as default};
